arguments.shader:
vec3 paletteToSrgb(vec3 c) {
 return mix(12.92*c, 1.055*pow(max(c,vec3(0.0)),vec3(1.0/2.4))-0.055, step(vec3(0.0031308),c));
}
int rank2(ivec2 p) {
 return ((p.x ^ p.y)&1)*2+(p.y&1);
}
void main() {
 vec4 src=texture(u_input,v_uv);
 float luma=dot(src.rgb,vec3(0.2126,0.7152,0.0722));
 luma=clamp((luma-0.5)*p_contrast+0.5,0.0,1.0);
 ivec2 cell=ivec2(floor(v_uv*u_resolution/float(p_cell_size)));
 int rank=rank2(cell)*4+rank2(cell>>1);
 float ordered=(float(rank)+0.5)/16.0-0.5;
 float mask=step(p_threshold,luma+ordered*p_dither);
 if(p_invert) mask=1.0-mask;
 outColor=vec4(paletteToSrgb(mix(p_ink,p_paper,mask)),src.a);
}

